from domain import view

class API:
    def __init__(self, store):
        self.store = store

    def get(self, owner, order_id):
        order = self.store.get(order_id)
        if order is None or order.owner != owner:
            return 404, {'error': 'not found'}
        return 200, view(order)

    def cancel(self, owner, order_id, key):
        if not isinstance(key, str) or not key:
            return 400, {'error': 'invalid key'}

        scoped_key = (owner, key)
        previous = self.store.cancellations.get(scoped_key)
        if previous is not None:
            previous_id, body = previous
            if previous_id != order_id:
                return 409, {'error': 'key already used'}
            return 200, dict(body)

        order = self.store.get(order_id)
        if order is None or order.owner != owner:
            return 404, {'error': 'not found'}
        if order.state != 'paid':
            return 409, {'error': 'order cannot be cancelled'}

        order.state = 'cancelled'
        self.store.refunds.append((order.id, order.cents))
        body = {'id': order.id, 'state': order.state, 'refunded': order.cents}
        self.store.cancellations[scoped_key] = (order.id, dict(body))
        return 200, body

