class Client:
    def __init__(self, api, owner):
        self.api, self.owner = api, owner

    def get(self, order_id):
        status, body = self.api.get(self.owner, order_id)
        if status != 200:
            raise ValueError(status)
        return body

    def cancel(self, order_id, key):
        status, body = self.api.cancel(self.owner, order_id, key)
        if status != 200:
            raise ValueError(status)
        return body

